import re, shutil
from pathlib import Path
from datetime import datetime

home = Path.home()
dl, dk, ht = home/"Downloads", home/"Desktop", home/"Documents/合同"
log = []

def move(src: Path, dest_dir: Path):
    dest_dir.mkdir(parents=True, exist_ok=True)
    target = dest_dir/src.name
    if target.exists():
        log.append(f"  跳过(目标已存在): {src.name}")
        return
    shutil.move(str(src), str(target))

# ---------- 1. 发票按月归档 ----------
inv_map = {
    "Invoice_Figma_2026-09.pdf":   "2026-09",
    "Invoice_GitHub_2026-10.pdf":  "2026-10",
    "发票_阿里云_2026-08.pdf":      "2026-08",
    "发票_阿里云_2026-09.pdf":      "2026-09",
    "餐饮发票_2026-09-12.pdf":      "2026-09",
    "滴滴出行电子发票_10月.pdf":     "2026-10",   # 今年10月
}
for f, month in inv_map.items():
    src = dl/f
    if not src.exists():
        continue
    move(src, dl/"发票"/month)
    log.append(f"发票  {f}  ->  发票/{month}/")

# 京东发票: 内容无日期, 用 mtime 推断; 若 mtime 是今天则不动
p = dl/"增值税电子普通发票_京东_显示器.pdf"
if p.exists():
    mt = datetime.fromtimestamp(p.stat().st_mtime)
    today = datetime.now()
    if (mt.year, mt.month, mt.day) == (today.year, today.month, today.day):
        jd_note = f"京东发票 mtime={mt:%Y-%m-%d %H:%M} 即今天, 日期不可信, 未归档"
    else:
        month = f"{mt.year}-{mt.month:02d}"
        move(p, dl/"发票"/month)
        log.append(f"京东发票  ->  发票/{month}/  (依据文件时间 {mt:%Y-%m-%d})")
        jd_note = f"京东发票按文件时间 {mt:%Y-%m-%d} 归入 {month}"
else:
    jd_note = "京东发票已不在 Downloads(可能已归档)"
    for c in (dl/"发票").rglob("*京东*"):
        jd_note = f"京东发票已在 {c.parent.name}/"

# ---------- 2. 桌面截图按日期归档 ----------
for f in sorted(dk.glob("截图 *.png")):
    m = re.search(r"(\d{4}-\d{2}-\d{2})", f.name)
    if not m:
        log.append(f"截图  {f.name}  未动 (文件名无日期)"); continue
    move(f, dk/"截图"/m.group(1))
    log.append(f"截图  {f.name}  ->  截图/{m.group(1)}/")

# ---------- 3. 合同改名 日期-对方 ----------
ren = {
    "星河设计服务合同.pdf": "2026-03-15-星河设计.pdf",
    "远山贸易采购合同.pdf": "2026-08-20-远山贸易.pdf",
    "青木物业租赁协议.pdf": "2026-05-02-青木物业.pdf",
}
for old, new in ren.items():
    if (ht/old).exists() and not (ht/new).exists():
        (ht/old).rename(ht/new)
        log.append(f"合同  {old}  ->  {new}")
    else:
        log.append(f"合同  {old} 跳过(源缺失或目标已存在)")

print("\n".join(log))
print("\n京东:", jd_note)

# ---------- 验证 ----------
print("\n===== Downloads/发票 =====")
for p in sorted((dl/"发票").rglob("*")):
    if p.is_file(): print("  ", p.relative_to(dl))
print("===== Desktop/截图 =====")
for p in sorted((dk/"截图").rglob("*")):
    if p.is_file(): print("  ", p.relative_to(dk))
print("===== Documents/合同 =====")
for p in sorted(ht.iterdir()): print("  ", p.name)
print("===== Downloads 残留发票/收据类文件 =====")
for p in sorted(dl.iterdir()):
    if p.is_file() and re.search(r"发票|Receipt|收据|水单", p.name):
        print("  ", p.name)
print("===== Desktop 根目录残留 =====")
for p in sorted(dk.iterdir()): print("  ", p.name)

