import os, re, shutil, datetime

home = os.path.expanduser("~")
dl = os.path.join(home, "Downloads")
dt = os.path.join(home, "Desktop")
ht = os.path.join(home, "Documents", "合同")

def safe_move(src, dst_dir, name=None):
    name = name or os.path.basename(src)
    os.makedirs(dst_dir, exist_ok=True)
    dst = os.path.join(dst_dir, name)
    if os.path.exists(dst):
        print(f"!! 目标已存在，跳过: {dst}")
        return None
    shutil.move(src, dst)
    return dst

print("========== 任务1: 下载/发票 按月归档 ==========")
inv_root = os.path.join(dl, "发票归档")
# (文件名, 月份)  月份None表示用文件创建时间兜底
invoices = {
    "2026-08": ["发票_阿里云_2026-08.pdf"],
    "2026-09": ["Invoice_Figma_2026-09.pdf", "发票_阿里云_2026-09.pdf", "餐饮发票_2026-09-12.pdf"],
    "2026-10": ["Invoice_GitHub_2026-10.pdf", "滴滴出行电子发票_10月.pdf"],
    None:      ["增值税电子普通发票_京东_显示器.pdf"],
}
for month, files in invoices.items():
    for fn in files:
        src = os.path.join(dl, fn)
        if not os.path.exists(src):
            print(f"!! 找不到: {fn}"); continue
        if month is None:
            st = os.stat(src)
            btime = getattr(st, "st_birthtime", st.st_mtime)
            m = datetime.datetime.fromtimestamp(btime).strftime("%Y-%m")
            note = f"(文件名/内容无日期，按文件时间归入 {m})"
        else:
            m, note = month, ""
        dst = safe_move(src, os.path.join(inv_root, m))
        if dst: print(f"✓ {fn}  ->  发票归档/{m}/  {note}")

print("\n========== 任务2: 桌面截图 按日期归档 ==========")
shot_root = os.path.join(dt, "截图")
for fn in sorted(os.listdir(dt)):
    m = re.match(r"^截图 (\d{4}-\d{2}-\d{2}) ", fn)
    if m and fn.endswith(".png"):
        dst = safe_move(os.path.join(dt, fn), os.path.join(shot_root, m.group(1)))
        if dst: print(f"✓ {fn}  ->  截图/{m.group(1)}/")

print("\n========== 任务3: 文档/合同 改名为 日期-对方 ==========")
renames = {
    "星河设计服务合同.pdf": "2026-03-15-星河设计.pdf",
    "远山贸易采购合同.pdf": "2026-08-20-远山贸易.pdf",
    "青木物业租赁协议.pdf": "2026-05-02-青木物业.pdf",
}
for old, new in renames.items():
    src = os.path.join(ht, old); dst = os.path.join(ht, new)
    if not os.path.exists(src):
        print(f"!! 找不到: {old}"); continue
    if os.path.exists(dst):
        print(f"!! 目标已存在，跳过: {new}"); continue
    os.rename(src, dst)
    print(f"✓ {old}  ->  {new}")

print("\n========== 完成后核对 ==========")
for label, root in [("发票归档", inv_root), ("Desktop/截图", shot_root), ("文档/合同", ht)]:
    print(f"--- {label} ---")
    for cur, dirs, files in os.walk(root):
        rel = os.path.relpath(cur, root)
        for f in sorted(files):
            print(f"  {rel + '/' if rel != '.' else ''}{f}")

