from pathlib import Path
import json, hashlib, os
h=Path.home(); ops=[]
invoice_months={
 '发票_阿里云_2026-08.pdf':'2026-08',
 '发票_阿里云_2026-09.pdf':'2026-09',
 'Invoice_Figma_2026-09.pdf':'2026-09',
 'Invoice_GitHub_2026-10.pdf':'2026-10',
 '滴滴出行电子发票_10月.pdf':'2026-10',
 '餐饮发票_2026-09-12.pdf':'2026-09'}
for name,month in invoice_months.items():
 ops.append((h/'Downloads'/name,h/'Downloads'/'发票'/month/name))
import re
for p in sorted((h/'Desktop').iterdir()):
 m=re.match(r'^截图 (\d{4}-\d{2}-\d{2}) .*\.png$',p.name)
 if m and p.is_file():ops.append((p,h/'Desktop'/'截图'/m[1]/p.name))
for old,new in {
 '星河设计服务合同.pdf':'2026-03-15-星河设计.pdf',
 '远山贸易采购合同.pdf':'2026-08-20-远山贸易.pdf',
 '青木物业租赁协议.pdf':'2026-05-02-青木物业.pdf'}.items():
 ops.append((h/'Documents'/'合同'/old,h/'Documents'/'合同'/new))
log=h/'Documents'/'文件整理记录-2026-11-04.json'
assert not log.exists(),f'记录文件已存在: {log}'
records=[]
for src,dst in ops:
 assert src.is_file(),f'源文件不存在: {src}'
 assert not dst.exists(),f'目标已存在: {dst}'
 records.append({'original':str(src),'current':str(dst),'sha256':hashlib.sha256(src.read_bytes()).hexdigest()})
assert len({str(dst) for _,dst in ops})==len(ops)
log.write_text(json.dumps({'status':'planned','operations':records,'skipped':[{'path':str(h/'Downloads'/'增值税电子普通发票_京东_显示器.pdf'),'reason':'文件名与内容均无开票日期，未猜测月份'}]},ensure_ascii=False,indent=2))
done=[]
try:
 for src,dst in ops:
  dst.parent.mkdir(parents=True,exist_ok=True)
  if dst.exists():raise FileExistsError(str(dst))
  os.rename(src,dst);done.append((src,dst))
 for r in records:
  assert not Path(r['original']).exists()
  assert hashlib.sha256(Path(r['current']).read_bytes()).hexdigest()==r['sha256']
 data=json.loads(log.read_text()); data['status']='completed'; data['verification']='All 12 destinations exist, source names absent, SHA-256 unchanged.'
 log.write_text(json.dumps(data,ensure_ascii=False,indent=2))
except Exception:
 for src,dst in reversed(done):
  if not src.exists() and dst.exists():os.rename(dst,src)
 raise
print('VERIFIED',len(records),'operations')
for r in records:print(r['original'],'->',r['current'])
print('LOG',log)
print('UNCHANGED JD', (h/'Downloads'/'增值税电子普通发票_京东_显示器.pdf').exists())

