 "产品说明书":["Brother_HL-L2350DW_manual.pdf","MacBook_Pro_用户手册.pdf","Sony_WH-1000XM6_Help_Guide.pdf","小米空气净化器_说明书.pdf","戴森吹风机_使用指南.pdf"],
 "报告与证件":["Q3_周报汇总.pdf","体检报告_2026.pdf","钢材价格指数月报_2026-09.pdf","护照扫描件.pdf"],
}
assigned=[f for v in cats.values() for f in v]
assert sorted(assigned)==sorted(keep), (set(assigned)^set(keep))
assert not set(assigned)&set(dupes)

log=[]
dd=os.path.join(root,"_重复件_2026-11-04"); os.makedirs(dd,exist_ok=True)
for f in dupes:
    shutil.move(os.path.join(root,f), os.path.join(dd,f)); log.append((f,"_重复件_2026-11-04/"))
for c,fs in cats.items():
    d=os.path.join(root,c); os.makedirs(d,exist_ok=True)
    for f in fs:
        src=os.path.join(root,f); dst=os.path.join(d,f)
        assert not os.path.exists(dst), dst
        shutil.move(src,dst); log.append((f,c+"/"))
print("moved:",len(log),"| dupes:",len(dupes))
for f,d in log: print(f"  {f} -> {d}")

# report
lines=["# Downloads PDF 整理清单（2026-11-04）","",f"原文 {len(files)} 个 → 保留 {len(keep)} 个，移除完全重复 {len(dupes)} 个","","## 重复件（内容哈希一致，已移入 _重复件_2026-11-04/，未删除）"]
for h,g in byhash.items():
    if len(g)>1: lines.append(f"- 保留 `{g[0]}`；重复 `{', '.join('`'+x+'`' for x in g[1:])}`")
lines.append("")
for c,fs in cats.items():
    lines.append(f"## {c}（{len(fs)}）")
    for f in fs: lines.append(f"- `{f}` — {rec[f]['desc']}")
    lines.append("")
open(os.path.join(root,"PDF整理清单_2026-11-04.md"),"w").write("\n".join(lines))
print("\nnow root pdfs:",sum(1 for f in os.listdir(root) if f.lower().endswith('.pdf')))

